#pragma once
#include "g1_natural_driver.h"
#include "full_content.h"
#include "hunter_behavior.h"
#include <iostream>
struct PianoDriver:Driver{
 using Driver::Driver;
 int shots{};
 void press(InputAction a=InputAction::Confirm){tick(key(a));tick();}
 // Enemy updates may reject this very frame; acknowledge the actual menu before selecting.
 void openMenu(){need(!game.raised(),"Public menu request still has a raised weapon");for(int n=0;n<600&&game.mode()==ApplicationMode::Playing;++n){need(game.session().hp()>0,"Public menu recovery died");if(game.session().flag(10)||game.session().flag(45)){tick(n%2==0?key(n%4==0?InputAction::Up:InputAction::Left):InputFrame{});}else if(n%2==0){press(InputAction::Cancel);}else{tick();}}need(game.mode()==ApplicationMode::Equipment,"Public menu request did not reach equipment");}
 void select(int id){auto v=game.menuView();auto it=std::find_if(v.rows.begin(),v.rows.end(),[&](const auto& row){return row.id==id;});need(it!=v.rows.end(),"Missing07 menu row "+std::to_string(id)+" mode="+std::to_string(int(game.mode()))+" raised="+std::to_string(game.raised())+" S1="+std::to_string(game.session().flag(1))+" S18="+std::to_string(game.session().flag(18))+" S17="+std::to_string(game.session().flag(17))+" S19="+std::to_string(game.session().flag(19))+" S10="+std::to_string(game.session().flag(10))+" S45="+std::to_string(game.session().flag(45))+" foreground="+std::to_string(int(game.foreground())));int target=int(it-v.rows.begin());for(int n=0;n<int(v.rows.size())&&game.menuView().selection!=target;++n){press(v.columns==2?InputAction::Right:InputAction::Down);}need(game.menuView().selection==target,"Selection stalled");press();}
 void actObject(const std::string& id){auto actor=findCharacter(game.world(),id);auto target=actor.motion.tile();if(actor.layer!=1){walk(target);settle();tick(key());settle();return;}for(Direction side:{Direction::Down,Direction::Left,Direction::Right,Direction::Up}){auto from=adjacentTile(target,side);if(game.world().player().motion.tile()!=from&&!next(game.world(),from)){continue;}auto face=side==Direction::Down?Direction::Up:side==Direction::Up?Direction::Down:side==Direction::Left?Direction::Right:Direction::Left;actAt(from,face);return;}throw std::runtime_error("No07 object adjacency "+id);}
 void saveAt(int slot){walk({9,10});move(Direction::Up);tick(key());need(game.mode()==ApplicationMode::Saving,"07 legal save absent");for(int n=0;n<200;++n){tick();}tick(key());need(game.fileMenuView().has_value(),"07 slots absent");for(int n=1;n<slot;++n){tick(key(InputAction::Down));}tick(key());need(game.mode()==ApplicationMode::Playing,"07 save failed");}
 void equip(int id,int slot=1){if(game.session().equipped(slot)==id){return;}openMenu();select(2);select(slot);select(id);press(InputAction::Cancel);press(InputAction::Cancel);need(game.session().equipped(slot)==id,"07 equip failed");}
 void lower(InputAction posture=InputAction::Weapon){for(int n=0;n<24;++n){InputFrame in;in.buttons[int(posture)].held=true;tick(in);}for(int n=0;n<100;++n){tick();}need(!game.raised(),"07 lower failed");}
 void item(int id){openMenu();select(0);select(id);if(game.mode()==ApplicationMode::Equipment&&game.menuView().page==MenuPage::Target){press();}if(game.mode()==ApplicationMode::Equipment){closeMenu();}}
 void closeMenu(){while(game.mode()==ApplicationMode::Equipment&&game.menuView().page!=MenuPage::Root){press(InputAction::Cancel);}if(game.mode()==ApplicationMode::Equipment){press(InputAction::Cancel);}need(game.mode()==ApplicationMode::Playing,"07 menu close failed");}
 void hallPiano(){actObject("m132-e4");need(game.mapId()==136,"07 inner corridor absent");actObject("m136-e6");need(game.mapId()==137,"07 piano entry absent");walk({17,7});settle();move(Direction::Up);}
 void pianoHall(){actObject("m137-e12");need(game.mapId()==136,"07 piano return absent");actObject("m136-e5");need(game.mapId()==132,"07 hall return absent");}
 void choices(int choice){std::uint64_t request{};int first{};for(int n=0;n<20000;++n){if(game.foreground()==ForegroundKind::None&&!game.dialogue().active()&&!game.world().player().motion.moving()){return;}InputFrame in=n%8==0?key():InputFrame{};auto v=game.inputPromptView();if(v.cursor){if(request!=v.request){request=v.request;first=v.cursor->line;}in=key(v.cursor->line==first+choice?InputAction::Confirm:InputAction::Down);}tick(in);}throw std::runtime_error("07 choices stalled");}
};
inline void battle(PianoDriver& run){
 int shots=0,fired=0;for(int n=0;n<20000;++n){auto& game=run.game;auto& s=game.session();need(s.hp()>0,"Natural07 battle died");const int rounds=s.magazine(s.equipped(1));std::vector<std::string> alive;for(const auto& [id,e]:game.content().enemies){if(e.map==game.mapId()&&!s.flag(e.deadFlag)){alive.push_back(id);}}if(alive.empty()){break;}InputFrame in;
 if(game.foreground()!=ForegroundKind::None||game.dialogue().active()){if(n%8==0){in=key();}}
 else if(!game.raised()){in=key(InputAction::Weapon);}
 else{const auto p=game.world().player().motion.tile();auto id=*std::min_element(alive.begin(),alive.end(),[&](const auto& a,const auto& b){auto x=findCharacter(game.world(),a).motion.tile(),y=findCharacter(game.world(),b).motion.tile();return std::abs(x.x-p.x)+std::abs(x.y-p.y)<std::abs(y.x-p.x)+std::abs(y.y-p.y);});const auto t=findCharacter(game.world(),id).motion.tile();const int dx=t.x-p.x,dy=t.y-p.y;const Direction face=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
 if(n%200==0){std::cout<<"FIGHT map="<<game.mapId()<<" n="<<n<<" p="<<p.x<<","<<p.y<<" target="<<id<<"/"<<t.x<<","<<t.y<<" HP="<<s.hp()<<" ammo="<<s.magazine(s.equipped(1))<<" state="<<s.variable(game.content().enemies.at(id).rules.at("state_variable"))<<" dmg="<<s.variable(game.content().enemies.at(id).rules.at("damage_variable"))<<'\n';}
 if((dx&&dy)||std::abs(dx)+std::abs(dy)>4){for(Direction side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){const auto step=next(game.world(),adjacentTile(t,side));if(step){in.movement=step;break;}}}
 else if(game.world().player().motion.facing()!=face){in.buttons[int(InputAction::Weapon)].held=true;in.movement=face;}else if(n%6==0){in=key(InputAction::Attack);++shots;}}
 run.tick(in);fired+=std::max(0,rounds-run.game.session().magazine(run.game.session().equipped(1)));if(n==19999){throw std::runtime_error("Natural07 battle stalled");}
 }
 for(int attempt=0;attempt<3&&run.game.raised();++attempt){for(int n=0;n<24;++n){InputFrame in;in.buttons[int(InputAction::Weapon)].held=true;run.tick(in);}for(int n=0;n<60;++n){run.tick();}run.settle();}need(!run.game.raised(),"Public Shift gesture failed to lower after battle");run.settle();if(run.game.session().hp()<80&&run.game.session().count(5)>0){run.item(5);}std::cout<<"REAL07 map="<<run.game.mapId()<<" attackPresses="<<shots<<" roundsFired="<<fired<<" HP="<<run.game.session().hp()<<" count="<<run.game.session().variable(35)<<'\n';
}
